				o.r = Integer.parseInt(sa[2]);
				o.d = Math.abs(o.l - o.r);
				arr[i] = o;
			}
			Arrays.sort(arr, (o1, o2) -> o2.d - o1.d);

			TreeSet<Integer> set = new TreeSet<>();
			for (int i = 1; i <= n; i++) {
				set.add(i);
			}

			long ans = 0;
			Set<Obj> ok = new HashSet<>();
			Set<Obj> ng = new HashSet<>();
			for (Obj o : arr) {
				if (o.l == o.r) {
					ok.add(o);
				} else if (o.l > o.r) {
					Integer m = set.floor(o.k);
					if (m == null) {
						ng.add(o);
					} else {
						set.remove(m);
						ans += o.l;
					}
				} else {
					Integer m = set.higher(o.k);
					if (m == null) {
						ng.add(o);
					} else {
						set.remove(m);
						ans += o.r;
					}
				}
			}
			for (Obj o : ok) {
				ans += Math.max(o.l, o.r);
			}
			for (Obj o : ng) {
				ans += Math.min(o.l, o.r);
			}
			pw.println(ans);
		}
