public class Main {

	static class Dic implements Comparable<Dic>{
		String moji;
		int page;
		Dic(String moji, int page){
			this.moji=moji;
			this.page=page;
		}
		public int compareTo(Dic d) {
			if(this.moji.equals(d.moji)) {
				return this.page-d.page;
			}
			else {
				return this.moji.compareTo(d.moji);
			}
		}
	}

