class UnionSet:
    def __init__(self, nmax: int) -> None:
        self.size = [1] * nmax
        self.id = [i for i in range(nmax)]
        self.weight = [0] * nmax

    def root(self, i: int) -> int:
        if (i == self.id[i]):
            return i
        else:
            tmp = self.root(self.id[i])
            self.weight[i] += self.weight[self.id[i]]
            self.id[i] = tmp
            return self.id[i]

    def get_weight(self, i: int) -> int:
        self.root(i)
        return self.weight[i]

    def connected(self, p: int, q: int) -> bool:
        return self.root(p) == self.root(q)

    def unite(self, p: int, q: int, w: int) -> None:
        w += self.get_weight(p)
        w -= self.get_weight(q)
        i, j = self.root(p), self.root(q)
        if (i == j):
            return
        if self.size[i] < self.size[j]:
            self.id[i] = j
            self.size[j] += self.size[i]
            self.weight[i] = -w
        else:
            self.id[j] = i
            self.size[i] += self.size[j]
            self.weight[j] = w

    def diff(self, p: int, q: int) -> None:
        i, j = self.root(p), self.root(q)
        if (i == j):
            print(self.get_weight(q) - self.get_weight(p))
