				kle++;
			} else {
				kri++;
			}
		}

		return weight[id] = le * kle + ri * kri;
	}

	public static int gcd(int x, int y) {
		if (x < y) {
			int swap = x;
			x = y;
			y  =swap;
		}
		if (y == 0) {
			return x;
		}

		return gcd(y, x % y);
	}

