			int[] score = new int[m];
			int[] name = new int[m];
			for (int i = 0; i < n; i++) {
				str = br.readLine();
				String[] answer = str.split(" ");
				for (int j = 0; j < m; j++) {
					score[j] = score[j] + Integer.parseInt(answer[j]);
					name[j] = j + 1;
				}
			}
			name = Sort(score, name);
			for (int i=0;i<m;i++) {
				System.out.print(name[i]);
				if(i!=m-1)
					System.out.print(" ");
			}
			System.out.println();
			str = br.readLine();
		}
	}

	private static int[] Sort(int[] num, int[] name) {
		int length = num.length;
		for (int i = 1; i < length - 1; i++) {
			for (int j = 0; j < length - i; j++) {
				if (num[j] < num[j + 1]) {
					int tmpnum = num[j];
					int tmpname = name[j];
					num[j] = num[j + 1];
					name[j] = name[j + 1];
					num[j + 1] = tmpnum;
					name[j + 1] = tmpname;
				}
			}
		}
		return name;
	}
}
