		if(n == 1) return 1;
		if(n == 0) return 0;
		if(map.containsKey(n)) return map.get(n);
		long ret;
		if(n % 2 ==  1){
			ret = (2*dfs(n/2) + dfs(n/2+1)) % MOD;
			map.put(n, ret);
		}else{
			ret = (2*dfs(n/2) + dfs(n/2-1)) % MOD;
			map.put(n, ret);
		}
		return ret;
	}

