	private static int[] Sort(int[] num, int[] name) {
		int length = num.length;
		for (int i = 1; i < length - 1; i++) {
			for (int j = 0; j < length - i; j++) {
				if (num[j] < num[j + 1]) {
					int tmpnum = num[j];
					int tmpname = name[j];
					num[j] = num[j + 1];
					name[j] = name[j + 1];
					num[j + 1] = tmpnum;
					name[j + 1] = tmpname;
				}
			}
		}
		return name;
	}
