def counting_sort(nmax, la):  # nmax:最大値, n:len(la), a:データリスト
	f = [0]*(nmax+1)
	nmax = 0
	for a in la:
		f[a] += 1
		if a > nmax: nmax = a
	k, i = len(la), nmax
	la = []
	while k:
