	public static long chinese_remainder(long[] as, long[] ms){
		long mul = 1;
		for(long m : ms){
			mul *= m;
		}

		long ret = 0;
		for(int i = 0; i < ms.length; i++){
			final long m = mul / ms[i];
			final long inv = mod_inv(m, ms[i]);

			long a = as[i] - as[i] / mul * mul;
			if(a < 0){
				a += mul;
			}

			ret = (ret + m * inv * as[i] % mul) % mul;
		}

		return ret;
	}

