		BigDecimal A = sqrt(new BigDecimal(a), 50);
		BigDecimal B = sqrt(new BigDecimal(b), 50);
		BigDecimal C = sqrt(new BigDecimal(c), 50);

		System.out.println(A);
		System.out.println(B);
		System.out.println(C);

