	private void dfs(int x, String s, int bit) {
		if (x == k) {
			set.add(s);
			return;
		}
		for (int i = 0; i < n; i++) {
			if (((bit >> i) & 1) == 1)
				continue;
			dfs(x + 1, s + num[i], bit | 1 << i);
		}
	}

	int n, k;
	int[] num;
	Set<String> set;
}
