		for (int i = 0; i < n; i++) {
			if (c[i] == 'D') {
				for (int j = 0; j <= i; j++) {
					dp[i + 1][j] += j * dp[i][j];
					dp[i + 1][j] %= MOD;
				}
			} else if (c[i] == 'U') {
				for (int j = 0; j <= i + 1; j++) {
					dp[i + 1][j + 1] += dp[i][j];
					dp[i + 1][j] += j * dp[i][j];
