		for (int i = 0; i < c.length; i++) {
			if (c[i] != 0)
				len++;
		}
		int[] ret = new int[len];
		int count = 0;
		for (int i = 0; i < c.length; i++) {
			if (c[i] != 0) {
				ret[count++] = c[i];
			}
		}
		return ret;
	}

