    static void solve()
    {
        while (true){
            int n = ni();
            if(n == 0)
                break;
            int[][] a = new int[n][n];
            for(int i = 0;i < n;i++){
                for(int j = 0;j < n;j++){
                    a[i][j] = ni();
                }
            }
            int[][] x = new int[n][n];

            for(int i = 0;i < n;i++){
                int min = Integer.MAX_VALUE, minj = -1;
                for(int j = 0;j < n;j++){
                    if(min > a[i][j]){
                        min = a[i][j];
                        minj = j;
                    }
                }
                for(int j = 0;j < n;j++){
                    if(a[i][minj] == min){
                        x[i][minj] |= 1;
                    }
                }
            }

            for(int i = 0;i < n;i++){
                int max = -1, maxj = -1;
                for(int j = 0;j < n;j++){
                    if(max < a[j][i]){
                        max = a[j][i];
                        maxj = j;
                    }
                }
                for(int j = 0;j < n;j++){
                    if(a[j][i] == max){
                        x[j][i] |= 2;
                    }
                }
            }

            Set<Integer> both = new HashSet<Integer>();
            for(int i = 0;i < n;i++){
                for(int j = 0;j < n;j++){
                    if(x[i][j] == 3){
                        both.add(a[i][j]);
                    }
                }
            }
            if(both.size() == 1){
